/**
 * Friends V2 API Tests
 */

import { SynapseEnhancedClient } from "../index.ts";
import { loadTestConfig } from "./config.ts";
import { logger } from "../../logger.ts";

const log = logger.getChild("enhanced:test:friends-api");

interface TestResult {
    name: string;
    passed: boolean;
    responseTime: number;
    error?: string;
    response?: any;
}

export class FriendsApiTests {
    private client: SynapseEnhancedClient;
    private config: ReturnType<typeof loadTestConfig>;

    public constructor() {
        this.config = loadTestConfig();
        this.client = new SynapseEnhancedClient({
            baseUrl: this.config.server.baseUrl,
            accessToken: this.config.server.accessToken,
            apiPrefix: this.config.server.apiPrefix,
            timeout: this.config.test.timeout,
        });
    }

    public async runAllTests(): Promise<TestResult[]> {
        log.info("");
        log.info("=============================");
        log.info("Running Friends V2 API Tests...");
        log.info("=============================");

        const results: TestResult[] = [];

        results.push(await this.testGetFriends());
        results.push(await this.testGetCategories());
        results.push(await this.testSearchUsers());
        results.push(await this.testGetPendingRequests());
        results.push(await this.testGetStatistics());

        this.printResults(results);
        return results;
    }

    private printResults(results: TestResult[]): void {
        for (const result of results) {
            const icon = result.passed ? "✓" : "✗";
            log.info(`${icon} ${result.name}: ${result.passed ? "PASSED" : "FAILED"} (${result.responseTime}ms)`);
            if (result.error) {
                log.error(`  Error: ${result.error}`);
            }
        }
        const passed = results.filter((r) => r.passed).length;
        log.info("");
        log.info(`Friends API Results: ${passed}/${results.length} passed`);
    }

    private async testGetFriends(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const friends = await this.client.friends.getFriends();

            return {
                name: "Get Friends List",
                passed: Array.isArray(friends),
                responseTime: Date.now() - startTime,
                response: { count: friends.length },
            };
        } catch (error: any) {
            return {
                name: "Get Friends List",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testGetCategories(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const categories = await this.client.friends.getCategories();

            return {
                name: "Get Categories",
                passed: Array.isArray(categories),
                responseTime: Date.now() - startTime,
                response: { count: categories.length },
            };
        } catch (error: any) {
            return {
                name: "Get Categories",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testSearchUsers(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const results = await this.client.friends.searchUsers("test", 5);

            return {
                name: "Search Users",
                passed: Array.isArray(results),
                responseTime: Date.now() - startTime,
                response: { count: results.length },
            };
        } catch (error: any) {
            return {
                name: "Search Users",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testGetPendingRequests(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const requests = await this.client.friends.getPendingRequests();

            return {
                name: "Get Pending Requests",
                passed: Array.isArray(requests),
                responseTime: Date.now() - startTime,
                response: { count: requests.length },
            };
        } catch (error: any) {
            return {
                name: "Get Pending Requests",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testGetStatistics(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const stats = await this.client.friends.getFriendStats();

            return {
                name: "Get Statistics",
                passed: typeof stats.total_friends === "number",
                responseTime: Date.now() - startTime,
                response: stats,
            };
        } catch (error: any) {
            return {
                name: "Get Statistics",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }
}

// Execute directly
const tests = new FriendsApiTests();
tests.runAllTests().catch((error) => log.error(error));
